/**
 * WhatsNewView Component
 * In-app "What's New" page — the Highlight of the CURRENT release plus its
 * full release notes. Linked from the sidebar widget.
 *
 * @purpose Show users what changed in the latest release
 * @used-by App.ts (route /whats-new)
 *
 * ── RELEASE WORKFLOW ─────────────────────────────────────────────────
 * The HIGHLIGHT and RELEASE constants below are REGENERATED by the /release
 * skill on every release (promotional highlight + compact notes of the new
 * version — English only, old content is replaced). Only edit them through
 * that workflow. Not translated (same as the Update Modal).
 */

import { View } from './View';
import { _ } from '../../i18n';

interface WhatsNewCategory {
  title: string;
  items: string[];
}

/** The big feature of the CURRENT release — promotional tone. */
// i18n-ok (release marketing text, English only)
const HIGHLIGHT =
  'DMs just got better: reply quotes show the original message right in the conversation (tap it to jump there instantly), plus a built-in emoji picker!';

/** Full release notes of the CURRENT version (replaced on every release). */
const RELEASE: {
  version: string;
  date: string;
  categories: WhatsNewCategory[];
} = {
  version: '1.9.11',
  date: 'November 2026',
  categories: [
    {
      title: 'DMs', // i18n-ok: WhatsNewView is English-only by design (like the update modal)
      items: [
        'Reply quotes: replies in a conversation show the original message as a quote — tap it to jump straight to that message.',
        'New emoji picker in conversations.',
        "Purged spam DMs can no longer come back, and senders you've purged stay hidden.",
      ],
    },
    {
      title: 'Communities', // i18n-ok: WhatsNewView is English-only by design (like the update modal)
      items: [
        'Community profiles shared in notes (kind 32222) now display as a proper community card instead of raw text.',
      ],
    },
    {
      title: 'Fixes', // i18n-ok: WhatsNewView is English-only by design (like the update modal)
      items: [
        'Relay fixes (by Mokhtar, via pull requests — thanks!): idle relays no longer crash, and evicted relays no longer reconnect endlessly (PRs #9 and #10).',
      ],
    },
  ],
};

export class WhatsNewView extends View {
  private container: HTMLElement;

  constructor() {
    super();
    this.container = document.createElement('div');
    this.container.className = 'view-content view-content--whats-new';
    this.render();
  }

  private render(): void {
    this.container.innerHTML = `
      <div class="back-padder">
        <h1 class="about-title">${_("What's New")}</h1>

        <div class="whats-new-highlight">
          <h2>${_('Highlight of v%s', RELEASE.version)}</h2>
          <p>${HIGHLIGHT}</p>
        </div>

        <section class="about-section">
          <h2>
            v${RELEASE.version}
            <span class="whats-new-release-date">${RELEASE.date}</span>
          </h2>
          ${RELEASE.categories
            .map(
              category => `
            <h3>${category.title}</h3>
            <ul>
              ${category.items.map(item => `<li>${item}</li>`).join('')}
            </ul>
          `
            )
            .join('')}
        </section>
      </div>
    `;
  }

  public getElement(): HTMLElement {
    return this.container;
  }

  public destroy(): void {
    this.container.remove();
  }
}
